package com.rastudio.commerce.user; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="refresh_token") public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="user_id",nullable=false) public Long userId; @Column(name="token_hash",nullable=false) public String tokenHash; @Column(name="expires_at",nullable=false) public LocalDateTime expiresAt; @Column(nullable=false) public boolean revoked; @Column(name="created_at",updatable=false) public LocalDateTime createdAt; @PrePersist void created(){createdAt=LocalDateTime.now();} }
